<?php

namespace Ourvoice\Resources;

use Ourvoice\Common\HttpClient;
use Ourvoice\Exceptions;
use Ourvoice\Objects;

/**
 * Class WhatsappSessions
 *
 * @package Ourvoice\Sdk\Resources
 */
class WhatsappSessions extends Base
{
    public function __construct(HttpClient $httpClient)
    {
        $this->object = new Objects\WhatsappSession();
        $this->setResourceName('whatsapp/sessions');

        parent::__construct($httpClient);
    }

    /**
     * Create a new WhatsApp session. No body is required, it is generated by the API.
     */
    public function create($object = null, ?array $query = null)
    {
        return parent::create($object ?? new \stdClass(), $query);
    }

    public function getQrCode(string $id)
    {
        $resourceName = $this->resourceName . '/' . $id . '/qr-code';

        [$status, $body] = $this->httpClient->performHttpRequest(HttpClient::REQUEST_GET, $resourceName);

        if ($body === null) {
            throw new Exceptions\ServerException('Got an invalid JSON response from the server.');
        }

        return json_decode($body, null, 512, \JSON_THROW_ON_ERROR);
    }

    public function disconnect(string $id)
    {
        $resourceName = $this->resourceName . '/' . $id . '/disconnect';

        [$status, $body] = $this->httpClient->performHttpRequest(HttpClient::REQUEST_PATCH, $resourceName);

        return $this->processRequest($status, $body);
    }

    public function reconnect(string $id)
    {
        $resourceName = $this->resourceName . '/' . $id . '/reconnect';

        [$status, $body] = $this->httpClient->performHttpRequest(HttpClient::REQUEST_PATCH, $resourceName);

        return $this->processRequest($status, $body);
    }
}
